import { Injectable, ɵɵpureFunctionV } from '@angular/core';
import { Router } from '@angular/router';
import swal from'sweetalert2';
declare function modal(accion: string): any;
declare function year(fechaNacimiento: any): any;
declare function NumeroALetras(numero: number): any;

@Injectable({
  providedIn: 'root'
})
export class GeneralesService {
  produccion = 2;
  logo = './assets/img/logo.png';
  imagen = "./img/default.png";
  img = 'data:image/png;base64,';
  tijeras = '- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -';
  meses = [
    { id: 1, nombre: 'Enero' },
    { id: 2, nombre: 'Febrero' },
    { id: 3, nombre: 'Marzo' },
    { id: 4, nombre: 'Abril' },
    { id: 5, nombre: 'Mayo' },
    { id: 6, nombre: 'Junio' },
    { id: 7, nombre: 'Julio' },
    { id: 8, nombre: 'Agosto' },
    { id: 9, nombre: 'Septiembre' },
    { id: 10, nombre: 'Octubre' },
    { id: 11, nombre: 'Noviembre' },
    { id: 12, nombre: 'Diciembre' },
  ];
  constructor(private router: Router) { }

  getUrl() {
    if (this.produccion === 0) {
      return 'https://api.lumieresiga.com/';
    } else if(this.produccion === 1){
      return 'https://prueba.lumieresiga.com/server/';
    } else if(this.produccion === 2){
      return 'http://localhost:3200/';
    }else {
      return '';
    }
  }

  async delay(ms: number){
    await new Promise<void>((resolve) =>{
      setTimeout(() => resolve(), ms)
    }).then(() => {});
  }

  mensajeCorrecto(mensaje: string) {
    swal.fire(mensaje, 'Correcto', 'success');
  }

  mensajeError(mensaje: string) {
    const toast = swal.mixin({
      toast: true,
      position: 'top-end',
      showConfirmButton: false,
      timer: 2000,
      timerProgressBar: true,
      didOpen: (toast) => {
        toast.addEventListener('mouseenter', swal.stopTimer)
        toast.addEventListener('mouseleave', swal.resumeTimer)
      },
      
    })
    toast.fire(mensaje, '', 'error');
  }

  getSesionToken() {
    return localStorage.getItem('token');
  }

  cerrarSesion() {
    localStorage.clear();
  }

  interpretarError(error: any) {
    if (typeof error === 'string') {
      this.mensajeError(error);
      return;
    }
    if (!error) {
      this.mensajeError('Ha ocurrido un error');
      return;
    }
    if(error.status === 500){
      const mensaje = {
        archivo: error.error?.file,
        linea: error.error?.line,
        mensaje: error.error?.message,
        usuario: localStorage.getItem('nombre'),
        url: error.url
      };
      this.mensajeError('Error en el servidor');
    }
    else if(error.status === 400){
      const msg = typeof error.error === 'string' ? error.error : (error.error?.message || 'Solicitud incorrecta');
      this.mensajeError(msg);
    }else if(error.status === 401) {
      this.mensajeError('Su sesión ha caducado');
      this.cerrarSesion();
      window.location.reload();
    }else if(error.status === 200){
      this.mensajeCorrecto('La respuesta no es un error pero asi es interpretada');
    }
    else if(error.status !== undefined && error.status !== null) {
      this.mensajeError('Error con código -' + error.status);
    } else if(error.message) {
      this.mensajeError(error.message);
    } else {
      this.mensajeError('Ha ocurrido un error inesperado');
    }
  }

  abrirModal() {
    modal('show');
  }

  cerrarModal() {
    modal('hide');
  }

  validarString(cadena: string) {
    if (cadena === null || cadena === '' || cadena === undefined) {
      return true;
    }
    return false;
  }

  validarEntero(entero: any) {
    if (
      entero === 0 ||
      entero === '0' ||
      entero === '' ||
      entero === null
    ) {
      return true;
    }
    return false;
  }
  
  milesNumeros(numero: string | number) {
    const parsed = typeof numero === 'number' ? numero : parseFloat(numero);
    const absVal = isNaN(parsed) ? 0 : Math.abs(parsed);
    const formatted = absVal.toFixed(2);
    return formatted.replace(/(\.\d+)|\B(?=(\d{3})+(?!\d))/g, (m, g1) => g1 || ",");
  }

  esNumero(numero: string) {
    let es = parseFloat(numero);
    return isNaN(es);
  }

  hoy() {
    var now = new Date();
    var day = ("0" + now.getDate()).slice(-2);
    var month = ("0" + (now.getMonth() + 1)).slice(-2);
    var today = now.getFullYear()+"-"+(month)+"-"+(day) ;

    return today;
  }

  eliminarDatoArray(arreglo: any, dato: any){
    let final: Array<any> = new Array<any>();
    if(arreglo !== undefined){
      arreglo.forEach((elemento: any) => {
        (elemento.id.toString() === dato.id.toString()) ? null : final.push(elemento);
      });
    }
    return final;
  }

  actualizarDatoArray(arreglo: any, dato: any){
    let final: Array<any> = new Array<any>();
    if(arreglo !== undefined){
      arreglo.forEach((elemento: any) => {
        dato.seleccionado = true;
        final.push((elemento.id.toString() === dato.id.toString()) ? dato : elemento);
      });
    }
    return final;
  }
  
  agregarDatoArray(arreglo: any, dato: any){
    let final: Array<any> = new Array<any>();
    if(arreglo !== undefined){
      arreglo.forEach((elemento: any) => {
        final.push(elemento);
      });
    }
    final.push(dato);
    return final;
  }

  sublista(lista: any, identificador: any, key: any){
    let final: Array<any> = new Array<any>();
    if(this.validarEntero(identificador)){
      return final;
    }
    if(lista !== undefined){
      lista.forEach((elemento: any) => {
        if(elemento[key].toString() === identificador.toString()){
          final.push(elemento);
        }
      });
    }
    return final;
  }

  busquedaGeneral(lista: any, encabezados: any, busqueda: any){
    let final: Array<any> = new Array<any>();
    if(busqueda === ""){
      return lista;
    }
    lista.forEach((elemento: any) => {
      let coincide = false;
      encabezados.forEach((encabezado: any) => {
        if(elemento[encabezado].toString().includes(busqueda.toString())){
          coincide = true;
        }
      });
      if(coincide){
        final.push(elemento);
      }
    });
    return final;
  }

  busquedaIdentificador(lista: any, identificador: any){
    try {
      let seleccionado: any;
      lista.forEach((elemento: any) => {
        if(elemento.id.toString() === identificador.toString()){
          seleccionado = elemento;
        }
      });
      return seleccionado;
    } catch (error) {
      return null;
    }
  }

  restantes(lista: any, identificador: any){
    try {
      let seleccionado = new Array();
      lista.forEach((elemento: any) => {
        if(elemento.id.toString() !== identificador.toString()){
          seleccionado.push(elemento);
        }
      });
      return seleccionado;
    } catch (error) {
      return null;
    }
  }

  activos(lista: any){
    let final: Array<any> = new Array<any>();
    if(lista !== undefined){
      lista.forEach((elemento: any) => {
        if(elemento.activo){
          final.push(elemento);
        }
      });
    }
    return final;
  }

  faltantes(lista: any, listado: any, llave: any){
    let final: Array<any> = new Array<any>();
    listado.forEach((elemento: any) => {
      let coincide = true;
      lista.forEach((registro: any) => {
        if(elemento.id.toString() === registro[llave].toString()){
          coincide = false;
        }
      });
      if(coincide && !final.includes(elemento)){
        final.push(elemento);
      }
    });
    return final;
  }

  numeroALetra(numero: number){
    let cantidad = NumeroALetras(numero);
    return cantidad;
  }

  iguales(lista: any, listado: any, llave: any){
    let final: Array<any> = new Array<any>();
    listado.forEach((elemento: any) => {
      let coincide = false;
      lista.forEach((registro: any) => {
        if(elemento.id === registro[llave]){
          coincide = true;
        }
      });
      if(coincide && !final.includes(elemento)){
        final.push(elemento);
      }
    });
    return final;
  }

  sublistaMultiples(lista: any, busqueda: any){
    let final: Array<any> = new Array<any>();
    let keys = Object.keys(busqueda);
    lista.forEach((elemento: any) => {
      let coincide = true;
      keys.forEach((key: any) => {
        if(!this.validarEntero(busqueda[key])){
          if(elemento[key].toString() !== busqueda[key].toString()){
            coincide = false;
          }
        }
      });
      if(coincide){
        elemento.seleccionado = false;
        final.push(elemento);
      }
    });
    return final;
  }

  sublistaMultiplesExterna(lista: any, busqueda: any, listado: any, llave: any){
    let final: Array<any> = new Array<any>();
    let keys = Object.keys(busqueda);
    lista.forEach((elemento: any) => {
      let coincide = true;
      keys.forEach((key: any) => {
        if(elemento[key].toString() !== busqueda[key].toString()){
          coincide = false;
        }
      });
      if(coincide){
        listado.forEach((registro: any) => {
          if(registro.id.toString() === elemento[llave].toString() && !final.includes(registro)){
            final.push(registro);
          }
        });
      }
    });
    return final;
  }

  registroSeleccionado(lista: any, busqueda: any){
    let keys = Object.keys(busqueda);
    let seleccion: any;
    lista.forEach((elemento: any) => {
      let coincide = true;
      keys.forEach((key: any) => {
        if(elemento[key].toString() !== busqueda[key].toString()){
          coincide = false;
        }
      });
      if(coincide){
        seleccion = elemento;
      }
    });
    return seleccion;
  }

  calendariosActuales(lista: any){
    let now = new Date();
    let arreglo = new Array();
    lista.forEach((element: any) => {
      let fin = new Date(element.fin);
      if(fin > now){
        arreglo.push(element);
      }
    });
    return arreglo;
  }

  edad(fechaNacimiento: any){
    return year(fechaNacimiento);
  }

  nombre(lista: any, id: any){
    let nombre = '';
    lista.forEach((element: any) => {
      if(element.id.toString() === id.toString()){
        nombre = element.nombre;
      }
    });
    return nombre;
  }

  dato(lista: any, id: any){
    let nombre: any;
    lista.forEach((element: any) => {
      if(element.id.toString() === id.toString()){
        nombre = element;
      }
    });
    return nombre;
  }

  registros(lista: any, dato: any, llave: any){
    let final: Array<any> = new Array<any>();
    lista.forEach((registro: any) => {
      if(dato === registro[llave]){
        final.push(registro);
      }
    });
    return final;
  }

  obtenerRestantes(principal: any[], secundaria: any[]): any[] {

    if (!Array.isArray(principal)) {
      return [];
    }
  
    if (!Array.isArray(secundaria) || secundaria.length === 0) {
      return principal;
    }
  
    return principal.filter(p =>
      !secundaria.some(s => s.id === p.id)
    );
  }

}
